from __future__ import annotations


def operator_private_chat_document() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ferro · 私人通道</title><style>
:root{color-scheme:dark;--bg:#07100d;--panel:#0b1712;--line:#21382f;--text:#edf6f1;--muted:#82978d;--accent:#70f3b2}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}button,textarea{font:inherit}a{color:var(--accent);text-decoration:none}.shell{width:min(100% - 24px,1100px);margin:auto}.top{position:sticky;top:0;z-index:5;background:rgba(7,16,13,.92);border-bottom:1px solid var(--line)}.topin{min-height:60px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{font-weight:800}.sub{color:var(--muted);font-size:.72rem}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:16px;padding:18px 0 28px}.card{border:1px solid var(--line);border-radius:16px;background:var(--panel)}.head{padding:15px 16px;border-bottom:1px solid var(--line)}.head h1,.head h2{margin:0}.head h1{font:500 1.45rem Georgia,serif}.head p{margin:5px 0 0;color:var(--muted);font-size:.74rem;line-height:1.45}.log{height:calc(100vh - 260px);min-height:420px;overflow:auto;padding:14px;display:grid;align-content:start;gap:10px}.msg{max-width:88%;padding:11px 13px;border-radius:14px;white-space:pre-wrap;line-height:1.5;font-size:.88rem}.operator{justify-self:end;background:#183a2c}.ferro{background:#10251c;border:1px solid rgba(112,243,178,.13)}.system{max-width:100%;color:var(--muted);background:transparent;border:1px dashed var(--line);font-size:.75rem}.meta{margin-top:5px;color:#60766a;font-size:.62rem}.composer{border-top:1px solid var(--line);padding:12px}.composer textarea{width:100%;min-height:82px;resize:vertical;border:1px solid #315244;border-radius:12px;background:#07130e;color:var(--text);padding:12px;outline:none}.actions{display:flex;gap:8px;align-items:center;justify-content:flex-end;margin-top:8px;flex-wrap:wrap}.btn{border:0;border-radius:10px;padding:10px 14px;font-weight:800;cursor:pointer;background:var(--accent);color:#07100d}.ghost{background:transparent;color:var(--text);border:1px solid var(--line)}.btn:disabled{opacity:.5;cursor:wait}.status{margin-right:auto;color:var(--muted);font-size:.7rem}.side{display:grid;align-content:start;gap:12px}.proposal{padding:13px;border-top:1px solid var(--line)}.proposal:first-child{border-top:0}.proposal h3{margin:0 0 6px;font-size:.9rem}.proposal p{margin:5px 0;color:var(--muted);font-size:.72rem;line-height:1.45}.pill{display:inline-flex;padding:3px 7px;border:1px solid var(--line);border-radius:999px;color:var(--accent);font-size:.58rem;font-weight:800}.empty{padding:16px;color:var(--muted);font-size:.75rem}.thinking{max-width:100%;border:1px dashed #315244;background:#0a1711;color:#9fc2b1}.memory{padding:10px 13px;border-top:1px solid var(--line)}.memory:first-child{border-top:0}.memory b{display:block;font-size:.72rem}.memory p{margin:4px 0 0;color:var(--muted);font-size:.7rem;line-height:1.4}
@media(max-width:800px){.layout{grid-template-columns:1fr}.log{height:58vh;min-height:360px}.proposal-list{max-height:250px;overflow:auto}.sub{display:none}}@media(max-width:520px){.shell{width:min(100% - 14px,1100px)}.layout{gap:10px;padding-top:10px}.card{border-radius:13px}.head{padding:12px}.log{padding:10px;min-height:330px}.msg{max-width:94%;font-size:.84rem}.actions .btn{flex:1}.status{width:100%;order:3}}
</style></head><body><header class="top"><div class="shell topin"><div><a class="brand" href="/operator/">Ferro · Operator</a><div class="sub">PRIVATE OWNER CHANNEL · persistent conversation</div></div><div style="display:flex;gap:8px"><a href="/operator/llm/">LLM 请求</a><a href="/operator/">控制台 →</a></div></div></header>
<main class="shell layout"><section class="card"><div class="head"><h1>和 Ferro 私下交流</h1><p>这里的对话属于 owner/operator 上下文，可形成 Goal Draft。正式目标仍需显式激活；隐藏思维链和密钥不会暴露。</p></div><div class="log" id="log"></div><div class="composer"><textarea id="message" maxlength="4000" placeholder="例如：我想让你在一个月内把 X 粉丝从 2000 提升到 5000，但先和我讨论你准备怎么理解这个目标。"></textarea><div class="actions"><span class="status" id="status">已连接到 Ferro 私人通道</span><button class="btn ghost" id="draft">从对话生成目标草案</button><button class="btn" id="send">发送</button></div></div></section>
<aside class="side"><section class="card"><div class="head"><h2>Goal Drafts</h2><p>Ferro 认为信息足够时会提出草案；你也可以主动生成。</p></div><div class="proposal-list" id="proposals"></div></section><section class="card"><div class="head"><h2>长期记忆</h2><p>核心身份始终保留；对话中稳定、未来仍有用的信息会进入长期记忆。</p></div><div id="memories"></div></section></aside></main>
<script>(()=>{const $=id=>document.getElementById(id);let busy=false;function addMsg(row){const d=document.createElement('div');d.className='msg '+(row.role||'system');const t=document.createElement('div');t.className='body';t.textContent=String(row.text||'');d.append(t);const m=document.createElement('div');m.className='meta';m.textContent=row.created_at?new Date(row.created_at).toLocaleString():'';d.append(m);$('log').append(d);return d}function renderHistory(rows){$('log').innerHTML='';if(!rows.length)addMsg({role:'system',text:'这是你和 Ferro 的私有、持久对话。先说目标、约束、疑问或想法都可以。'});else rows.forEach(addMsg);$('log').scrollTop=$('log').scrollHeight}
function details(p){const out=[];if(p.kind==='EXTERNAL_MISSION'){out.push((p.metric||'metric')+' '+(p.direction==='AT_MOST'?'≤':'≥')+' '+p.target);if(p.baseline!==null&&p.baseline!==undefined)out.push('baseline '+p.baseline);if(p.deadline)out.push('deadline '+p.deadline)}return out.join(' · ')}
function renderProposals(rows){const root=$('proposals');root.innerHTML='';if(!rows.length){const e=document.createElement('div');e.className='empty';e.textContent='还没有目标草案。继续对话，或点击“从对话生成目标草案”。';root.append(e);return}for(const p of rows){const c=document.createElement('div');c.className='proposal';const tag=document.createElement('span');tag.className='pill';tag.textContent=(p.status||'DRAFT')+' · '+(p.kind||'GENERAL');const h=document.createElement('h3');h.textContent=p.description||'Untitled goal';const why=document.createElement('p');why.textContent=p.reason||'';c.append(tag,h,why);const x=details(p);if(x){const q=document.createElement('p');q.textContent=x;c.append(q)}if(p.status==='DRAFT'){const b=document.createElement('button');b.className='btn';b.textContent='激活为正式 Goal';b.onclick=()=>activate(p.proposal_id,b);c.append(b)}else{const q=document.createElement('p');q.textContent='已进入 Ferro 的正式目标系统'+(p.goal_id?' · '+p.goal_id:'');c.append(q)}root.append(c)}}
function renderMemories(rows){const root=$('memories');root.innerHTML='';const core=(rows||[]).filter(x=>String(x.memory_id||'').startsWith('core:')),learned=(rows||[]).filter(x=>!String(x.memory_id||'').startsWith('core:')).slice(-10),show=[...core,...learned];if(!show.length){const e=document.createElement('div');e.className='empty';e.textContent='暂无长期记忆。';root.append(e);return}for(const m of show){const c=document.createElement('div');c.className='memory';const b=document.createElement('b');b.textContent=m.kind||'MEMORY';const p=document.createElement('p');p.textContent=m.text||'';c.append(b,p);root.append(c)}}
async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',...opt,headers:{'content-type':'application/json','x-operator-request':'1',...(opt.headers||{})}});let d={};try{d=await r.json()}catch{}if(r.status===401){location.href='/operator/';throw new Error('需要重新登录')}if(!r.ok)throw new Error(d.error||('HTTP '+r.status));return d}
async function refresh(){try{const d=await api('/operator/api/chat');renderHistory(d.history||[]);renderProposals(d.proposals||[]);renderMemories(d.memories||[])}catch(e){$('status').textContent=e.message}}
async function send(){if(busy)return;const box=$('message'),message=box.value.trim();if(!message)return;busy=true;$('send').disabled=true;$('draft').disabled=true;box.value='';addMsg({role:'operator',text:message,created_at:new Date().toISOString()});const thinking=addMsg({role:'system',text:'正在接收你的消息…'});thinking.classList.add('thinking');$('log').scrollTop=$('log').scrollHeight;try{const r=await fetch('/operator/api/chat/stream',{method:'POST',cache:'no-store',headers:{'content-type':'application/json','x-operator-request':'1'},body:JSON.stringify({message})});if(r.status===401){location.href='/operator/';throw new Error('需要重新登录')}if(!r.ok){let d={};try{d=await r.json()}catch{}throw new Error(d.error||('HTTP '+r.status))}const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',ferro=null,donePayload=null;while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);if(event.type==='status'){thinking.querySelector('.body').textContent=event.text||'Ferro 正在处理…';$('status').textContent=event.text||'Ferro 正在处理…'}else if(event.type==='delta'){if(!ferro){ferro=addMsg({role:'ferro',text:'',created_at:new Date().toISOString()})}ferro.querySelector('.body').textContent+=(event.text||'');$('log').scrollTop=$('log').scrollHeight}else if(event.type==='error'){throw new Error(event.error||'operator_chat_failed')}else if(event.type==='done'){donePayload=event}}}if(thinking.isConnected)thinking.remove();if(donePayload){renderHistory(donePayload.history||[]);renderProposals(donePayload.proposals||[]);renderMemories(donePayload.memories||[]);$('status').textContent=donePayload.memory_saved&&donePayload.memory_saved.length?'已回复，并更新长期记忆':(donePayload.proposal?'已回复，并提出 Goal Draft':'已收到 Ferro 回复')}else{$('status').textContent='回复流已结束'}}catch(e){if(thinking.isConnected)thinking.remove();$('status').textContent=e.message;await refresh()}finally{busy=false;$('send').disabled=false;$('draft').disabled=false;box.focus()}}
async function draft(){if(busy)return;busy=true;$('send').disabled=true;$('draft').disabled=true;$('status').textContent='Ferro 正在把对话整理成目标草案…';try{const d=await api('/operator/api/chat/goal-draft',{method:'POST',body:'{}'});renderHistory(d.history||[]);renderProposals(d.proposals||[]);renderMemories(d.memories||[]);$('status').textContent=d.proposal?'目标草案已生成':'Ferro 认为还需要继续讨论'}catch(e){$('status').textContent=e.message}finally{busy=false;$('send').disabled=false;$('draft').disabled=false}}
async function activate(id,b){b.disabled=true;try{const d=await api('/operator/api/chat/goals/'+encodeURIComponent(id)+'/activate',{method:'POST',body:'{}'});renderProposals(d.proposals||[]);renderHistory(d.history||[]);$('status').textContent='正式 Goal 已激活，Ferro 会继续推进'}catch(e){$('status').textContent=e.message;b.disabled=false}}
$('send').onclick=send;$('draft').onclick=draft;$('message').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();send()}});refresh();})();</script></body></html>'''


__all__ = ["operator_private_chat_document"]
